t.script:
(function() {
    'use strict';

    // Initialize Stripe
    const stripe = Stripe('');
    const elements = stripe.elements();

    // Create card element
    const cardElement = elements.create('card', {
        style: {
            base: {
                fontSize: '16px',
                color: '#32325d',
                fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
                '::placeholder': {
                    color: '#aab7c4'
                }
            },
            invalid: {
                color: '#dc3545',
                iconColor: '#dc3545'
            }
        }
    });

    cardElement.mount('#card-element');

    // Handle card errors
    cardElement.on('change', function(event) {
        const displayError = document.getElementById('card-errors');
        if (event.error) {
            displayError.textContent = event.error.message;
        } else {
            displayError.textContent = '';
        }
    });

    // Handle form submission
    const submitButton = document.getElementById('submit-payment');
    const buttonText = document.getElementById('button-text');
    const spinner = document.getElementById('spinner');

    submitButton.addEventListener('click', async function(e) {
        e.preventDefault();

        const cardholderName = document.getElementById('card-holder-name').value.trim();

        if (!cardholderName) {
            alert('Please enter cardholder name');
            return;
        }

        // Disable button and show spinner
        submitButton.disabled = true;
        buttonText.classList.add('d-none');
        spinner.classList.remove('d-none');

        try {
            // Create payment method
            const {paymentMethod, error} = await stripe.createPaymentMethod({
                type: 'card',
                card: cardElement,
                billing_details: {
                    name: cardholderName,
                }
            });

            if (error) {
                throw new Error(error.message);
            }

            console.log('Created payment method:', paymentMethod.id);
            console.log('Using publishable key:', ''.substring(0, 20));

            // Create subscription via backend
            const response = await fetch('/subscription/create_stripe', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        payment_method_id: paymentMethod.id,
                        subscription_type: '',
                        stripe_price_id: ''
                    }
                })
            });

            const result = await response.json();
            const data = result.result;

            if (data.status === 'success') {
                window.location.href = data.redirect;
            } else if (data.status === 'requires_action') {
                // Handle 3D Secure authentication
                const {error: confirmError} = await stripe.confirmCardPayment(
                    data.client_secret
                );

                if (confirmError) {
                    throw new Error(confirmError.message);
                } else {
                    window.location.href = '/my_subscription';
                }
            } else {
                throw new Error(data.message || 'Payment failed');
            }

        } catch (error) {
            console.error('Payment error:', error);
            alert('Payment failed: ' + error.message);

            // Re-enable button
            submitButton.disabled = false;
            buttonText.classList.remove('d-none');
            spinner.classList.add('d-none');
        }
    });
})();
